UPDATE recipes SET continent = 'Europe', history = 'Lemon Drizzle Cake is a quintessential British bake, moist sponge soaked with tangy lemon syrup. This beloved teatime treat represents the heart of British home baking culture, where simple cakes are elevated through perfection of technique and the quality of citrus.' WHERE slug = 'lemon-drizzle-cake';

